head.script:
scwin.screenId = "jldfil15800";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("keyword"))); } },
        { childId: "__rb0", fn: function () { return " 전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldfil15800: 진입 키 report 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil15800.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_48_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_48_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_48_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15800.img_48_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_pageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15800.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_krpReportList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_krpReportList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_krpReportList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_krpReportList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["fileSurFix"] != null && r["fileSurFix"] !== '') { if (typeof scwin.downKrpFile === 'function') { await scwin.downKrpFile(r["realName"], r["fileName"], r["fileDir"]); } else { console.error('[sdd] 행 동작 미정의: scwin.downKrpFile (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downKrpFile'); } return; }
        if (typeof scwin.searchDetail === 'function') { await scwin.searchDetail(r["isuSrtCd"], r["bycorpSeq"], r["partcYy"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchDetail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_krpReportList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    try { return await $c.data.downFile("/support/report.do", "", ($c.util.getComponent("dma_SearchReq") ? $c.util.getComponent("dma_SearchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fn_SearchDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_SearchDetail = async function () {
    try { return await $c.data.downFile("/support/report.do", "", ($c.util.getComponent("dma_SearchDetailReq") ? $c.util.getComponent("dma_SearchDetailReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fn_DownKrpFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_DownKrpFile = async function () {
    try { return await $c.data.downFile("http://www.krx.co.kr/servlets/exkrx/util/Download", "", ($c.util.getComponent("dma_DownKrpFileReq") ? $c.util.getComponent("dma_DownKrpFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.krpReportForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchKrpReport');
    frm.action = 'report.do';
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param _isurCd _bycorpSeq _partcYy
 * @returns
 * @hidden N
*/
scwin.searchDetail = async function (_isurCd, _bycorpSeq, _partcYy) {
    /* sdd-asis-lifecycle:begin fn_SearchDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.krpReportForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchKrpReportDetail');
    $c.util.getComponent('dma_SearchReq').set('isurCd', _isurCd);
    $c.util.getComponent('dma_SearchReq').set('bycorpSeq', _bycorpSeq);
    $c.util.getComponent('dma_SearchReq').set('partcYy', _partcYy);
    frm.action = 'report.do';
    await scwin.tx_fn_SearchDetail();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.downKrpFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param _realName _fileName _fileDir
 * @returns
 * @hidden N
*/
scwin.downKrpFile = async function (_realName, _fileName, _fileDir) {
    /* sdd-asis-lifecycle:begin fn_DownKrpFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_SearchReq').set('fileName', _fileName);
    $c.util.getComponent('dma_SearchReq').set('realName', _realName);
    $c.util.getComponent('dma_SearchReq').set('fileDir', _fileDir);
    await scwin.tx_fn_DownKrpFile();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_108_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_108_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_108.page' }); } scwin.search(); };
